192	     * @param animalClass The class to get the colour of.
193	     * 
194	     * @return The color to be used for a given class of animal.
195	     */
196	    private Color getColor(Class animalClass)
197	    {
198	        Color col = colors.get(animalClass);
199	        if(col == null) {
200	            // no color defined for this class
201	            return UNKNOWN_COLOR;
202	        }
203	        else {
204	            return col;
