        for (int t = 0; t < 24; t++) {
            if (!oldLogic(t).equals(newLogic(t))) {
                ok = false;
                System.out.println("MISMATCH t=" + t + " old=[" + oldLogic(t) + "] new=[" + newLogic(t) + "]");
            }
        }
        System.out.println(ok ? "getTimeString: ALL 24 VALUES IDENTICAL" : "getTimeString: DIFFERENCES FOUND");
    }
}

